const config = $('Config').first().json;
const baseUrl = `https://${config.INSTANCE_SUBDOMAIN}.administrateapp.com/beta#`;

const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

// Each input item is one page of the Event's Interests.
let event = null;
const interests = [];
for (const page of $input.all()) {
  const body = page.json;
  if (Array.isArray(body.errors) && body.errors.length > 0) {
    throw new Error(`Administrate returned errors: ${body.errors.map((error) => error.message).join('; ')}`);
  }
  const eventNode = body.data?.events?.edges?.[0]?.node;
  if (!eventNode) {
    continue;
  }
  if (!event) {
    event = eventNode;
  }
  for (const edge of eventNode.interests?.edges ?? []) {
    interests.push(edge.node);
  }
}

// No reservations or interests on the cancelled Event: nothing to send.
if (!event || interests.length === 0) {
  return [];
}

const eventDetails = {
  eventId: event.id,
  eventTitle: event.title,
  eventStart: event.start ? DateTime.fromISO(event.start).toFormat('dd/MM/yy HH:mm') : '',
  eventUrl: `${baseUrl}/events/events/${event.legacyId}`,
};

const owners = new Map();
const skipped = [];

for (const interest of interests) {
  const opportunity = interest.opportunity;
  const ownerContactId = opportunity?.owner?.contact?.id;

  if (!ownerContactId) {
    let reason = 'Opportunity owner has no linked Contact';
    if (!opportunity) {
      reason = 'Interest has no Opportunity';
    } else if (!opportunity.owner) {
      reason = 'Opportunity has no owner';
    }
    skipped.push({
      json: {
        status: 'skipped',
        reason,
        interestId: interest.id,
        opportunityId: opportunity?.id ?? null,
        opportunityName: opportunity?.name ?? null,
        accountName: opportunity?.account?.name ?? null,
        ...eventDetails,
      },
    });
    continue;
  }

  if (!owners.has(ownerContactId)) {
    owners.set(ownerContactId, {
      ownerContactId,
      ownerFirstName: opportunity.owner.firstName ?? '',
      opportunities: new Map(),
    });
  }

  const ownerGroup = owners.get(ownerContactId);
  if (!ownerGroup.opportunities.has(opportunity.id)) {
    ownerGroup.opportunities.set(opportunity.id, {
      opportunityId: opportunity.id,
      opportunityName: opportunity.name ?? '',
      accountName: opportunity.account?.name ?? '',
      opportunityUrl: `${baseUrl}/crm/opportunities/${opportunity.legacyId}`,
      interestCount: 0,
    });
  }
  ownerGroup.opportunities.get(opportunity.id).interestCount += 1;
}

const eventHtml = [
  `Cancelled Event: ${escapeHtml(eventDetails.eventTitle)}`,
  `Cancelled Event Start: ${escapeHtml(eventDetails.eventStart)}`,
  `Cancelled Event URL: ${escapeHtml(eventDetails.eventUrl)}`,
].join('<br>');

const notifications = [...owners.values()].map((ownerGroup) => {
  const opportunities = [...ownerGroup.opportunities.values()];
  const opportunityListHtml = opportunities.map((opportunity) => [
    `<li>Account: ${escapeHtml(opportunity.accountName)}`,
    `Opportunity: ${escapeHtml(opportunity.opportunityName)}`,
    `Opportunity URL: ${escapeHtml(opportunity.opportunityUrl)}</li>`,
  ].join('<br>')).join('');

  return {
    json: {
      status: 'notify',
      ownerContactId: ownerGroup.ownerContactId,
      ownerFirstNameHtml: escapeHtml(ownerGroup.ownerFirstName),
      opportunityCount: opportunities.length,
      opportunities,
      detailsHtml: `${eventHtml}<br><br>Affected Opportunities:<ul>${opportunityListHtml}</ul>`,
      ...eventDetails,
    },
  };
});

return [...notifications, ...skipped];
